/* @lc app=leetcode id=3728 lang=kotlin */ class Solution { fun countStableSubarrays(capacity: IntArray): Long = capacity.runningFold(0L) { a, b -> a + b }.let { P -> HashMap<Pair<Long, Long>, Int>().let { m -> (2 until capacity.size).fold(0L) { acc, r -> m.merge(capacity[r - 2].toLong() to P[r - 1], 1) { a, b -> a + b }.let { acc + (m[capacity[r].toLong() to P[r] - capacity[r]] ?: 0) } } } } }